'use client'

import * as React from 'react'
import { Slot } from 'radix-ui'
import { cn } from '@/lib/utils'
import { useSatinLabels } from '@/registry/satin/ui/labels'

/**
 * Link: text that goes somewhere. Calm by default: the text colour with a border/strong
 * underline that takes the text colour on hover, so a paragraph full of links stays readable.
 * `brand` colours it for the one link that should stand out; `muted` is for footers and meta
 * lines and only underlines on hover. Focus draws the 2px focus ring around it.
 *
 * `external` (on by itself with `target="_blank"`) adds a 12px ↗ after the text, says
 * "(opens in a new tab)" to screen readers and sets `rel="noopener noreferrer"`.
 *
 * For a router's link (Next.js, React Router) pass `asChild` and put it inside: it gets the
 * styles, the router keeps the navigation.
 */
export interface LinkProps extends React.ComponentProps<'a'> {
  variant?: 'default' | 'brand' | 'muted'
  underline?: 'always' | 'hover' | 'none'
  external?: boolean
  asChild?: boolean
}

const variantClass = {
  default: 'sa:text-text-default sa:decoration-border-strong sa:hover:decoration-current',
  brand: 'sa:text-status-brand-fg sa:decoration-status-brand-fg/40 sa:hover:decoration-current',
  muted: 'sa:text-text-muted sa:decoration-current sa:hover:text-text-default',
}

export function Link({
  variant = 'default',
  underline,
  external,
  asChild = false,
  target,
  rel,
  className,
  children,
  ...props
}: LinkProps) {
  const labels = useSatinLabels()
  const line = underline ?? (variant === 'muted' ? 'hover' : 'always')
  const isExternal = external ?? target === '_blank'
  const Comp = asChild ? Slot.Root : 'a'
  return (
    <Comp
      data-slot="link"
      data-variant={variant}
      target={target ?? (isExternal && !asChild ? '_blank' : undefined)}
      rel={rel ?? (isExternal ? 'noopener noreferrer' : undefined)}
      className={cn(
        'sa:rounded-xs sa:font-medium sa:underline-offset-[3px] sa:outline-none sa:[text-decoration-thickness:1px]',
        'sa:transition-[color,text-decoration-color,box-shadow] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
        'sa:focus-visible:[box-shadow:0_0_0_2px_var(--action-focus-ring)]',
        line === 'always' && 'sa:underline',
        line === 'hover' && 'sa:no-underline sa:hover:underline',
        line === 'none' && 'sa:no-underline',
        variantClass[variant],
        className,
      )}
      {...props}
    >
      {asChild ? (
        children
      ) : (
        <>
          {children}
          {isExternal && (
            <>
              <svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden className="sa:ml-0.5 sa:inline-block sa:align-[-1px]">
                <path d="M4 3H9V8M9 3L3 9" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" style={{ strokeWidth: 1.1 }} />
              </svg>
              <span className="sa:sr-only">{` ${labels.opensInNewTab}`}</span>
            </>
          )}
        </>
      )}
    </Comp>
  )
}
